package api.publica;
import java.sql.*;import java.time.LocalDateTime;import java.util.*;import config.ConexionBD;import servicio.RankingDeportivoService;import api.publica.RankingPublicoDTO.*;
public class RankingPublicoService {private final RankingDeportivoService ranking=new RankingDeportivoService();
 public List<Categoria> categorias(){String q="SELECT c.id,c.codigo,c.nombre,c.color_hex,COUNT(DISTINCT h.perfil_jugador_id) participantes FROM categorias_deportivas c LEFT JOIN historial_competitivo_perfiles h ON h.categoria_deportiva_id=c.id WHERE c.activo=TRUE GROUP BY c.id,c.codigo,c.nombre,c.color_hex,c.nivel_orden ORDER BY c.nivel_orden";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<Categoria>x=new ArrayList<>();while(r.next())x.add(new Categoria(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getInt(5)));return x;}catch(SQLException e){throw new RuntimeException("No se pudieron cargar las categorias publicas.",e);}}
 public Ranking buscar(long categoriaId){Categoria c=categorias().stream().filter(x->x.id()==categoriaId).findFirst().orElseThrow(()->new IllegalArgumentException("La categoria solicitada no existe."));var base=ranking.calcular(categoriaId);List<Fila> filas=base.stream().map(x->new Fila(x.posicion(),x.perfilId(),x.jugador(),iniciales(x.jugador()),x.puntos(),x.partidos(),x.victorias(),x.derrotas(),x.efectividad(),x.diferenciaSets(),x.diferenciaGames())).toList();int partidos=base.stream().mapToInt(RankingDeportivoService.Posicion::partidos).sum()/2;return new Ranking(c,filas.size(),partidos,ultimoResultado(categoriaId),filas);}
 public Auditoria auditar(long categoriaId,long perfilId){if(perfilId<=0)throw new IllegalArgumentException("El jugador no es valido.");var a=ranking.auditar(perfilId,categoriaId).stream().map(x->new Aporte(x.partidoId(),x.torneo(),x.categoria(),x.fase(),x.resultado(),x.base(),x.bonus(),x.total(),x.fecha())).toList();return new Auditoria(perfilId,categoriaId,LocalDateTime.now(),a);}
 private LocalDateTime ultimoResultado(long categoriaId){String q="SELECT MAX(fecha_resultado) FROM historial_competitivo_perfiles WHERE categoria_deportiva_id=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,categoriaId);try(ResultSet r=s.executeQuery()){if(r.next()){Timestamp t=r.getTimestamp(1);return t==null?null:t.toLocalDateTime();}return null;}}catch(SQLException e){throw new RuntimeException("No se pudo obtener la ultima actualizacion del ranking.",e);}}
 private String iniciales(String n){if(n==null||n.isBlank())return "PJ";String[] p=n.trim().split("\\s+");return (p[0].substring(0,1)+(p.length>1?p[p.length-1].substring(0,1):"")).toUpperCase();}
}
